package dev.jobflow.service;
import dev.jobflow.api.AuthDtos.*; import dev.jobflow.domain.*; import dev.jobflow.repo.UserRepository; import dev.jobflow.security.JwtService; import java.util.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder passwords; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;} @Transactional public TokenResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.findByEmailIgnoreCase(email).isPresent())throw new IllegalArgumentException("Email is already registered");AppUser u=users.save(new AppUser(email,passwords.encode(r.password()),Role.USER));return new TokenResponse(jwt.issue(u),"Bearer");} public TokenResponse login(LoginRequest r){AppUser u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!passwords.matches(r.password(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials");return new TokenResponse(jwt.issue(u),"Bearer");} }
